SELECT '#1 com_code MACT/DEVI'; SELECT GRP_CD,COM_CD,COM_VAL,USE_YN,SORT_ORD FROM ju_com_code WHERE GRP_CD IN ('MACT','DEVI') ORDER BY 1,2;
SELECT '#2 com_code_detail MACT/DEVI'; SELECT GRP_CD,COM_CD,COM_NM,COM_NM_KEY,COM_DESC_KEY FROM ju_com_code_detail WHERE GRP_CD IN ('MACT','DEVI') ORDER BY 1,2;
SELECT '#3 com_group MACT'; SELECT g.GRP_CD,g.USE_YN,g.SORT_ORD,d.GRP_NM,d.GRP_NM_KEY FROM ju_com_group g LEFT JOIN ju_com_group_detail d USING(GRP_CD) WHERE g.GRP_CD='MACT';
SELECT '#4 menu_action'; SELECT ACT_ID,MNU_ID,ACT_CD,ACT_KIND,HANDLER_ID,USE_YN,ENABLED_YN,SORT_ORD FROM ju_menu_action ORDER BY ACT_ID;
SELECT '#5 menu_action_detail'; SELECT * FROM ju_menu_action_detail ORDER BY ACT_ID;
SELECT '#6 protocol PTL_TYPE'; SELECT PTL_TYPE,COUNT(*) FROM ju_protocol GROUP BY PTL_TYPE ORDER BY 1;
SELECT '#7 DOTNET_VERSION'; SELECT SYS_CD,SYS_VAL FROM ju_sys WHERE SYS_CD='DOTNET_VERSION';
SELECT '#8 device type'; SELECT DEV_CD,DEV_TYPE FROM ju_device ORDER BY 1;
SELECT '#9 user'; SELECT u.LOGIN_ID,LENGTH(u.USER_PW_HASH),u.AUTH_ID,u.USE_YN,d.USER_NM,d.PW_CHANGE_DT IS NULL AS PW_CHANGE_REQUIRED FROM ju_user u LEFT JOIN ju_user_detail d USING(USER_ID) ORDER BY 1;
SELECT '#10 multi_lang JU-0A keys'; SELECT LANG_CD,RES_KEY,RES_VAL FROM ju_multi_lang WHERE RES_KEY LIKE 'CODE.MACT.%' OR RES_KEY LIKE 'GROUP.MACT.%' OR RES_KEY LIKE 'ACTION.DEVICE.%' OR RES_KEY LIKE 'CODE.YENO.YENO0002.%' OR RES_KEY LIKE 'GROUP.YSNO.%' OR RES_KEY IN ('DEVICE.CONNECT','DEVICE.CREATE','DEVICE.DELETE','DEVICE.DISCONNECT','DEVICE.GET','DEVICE.SEARCH','DEVICE.START','DEVICE.STATUS','DEVICE.STOP','DEVICE.UPDATE') ORDER BY 1,2;
SELECT '#11 auth AUTH_ATTR (9-digit kept)'; SELECT AUTH_ID,AUTH_TYPE,LEFT(AUTH_ATTR,40),LENGTH(AUTH_ATTR) FROM ju_auth ORDER BY 1;
